import {DataTable} from '@primer/react/experimental'
import type {CustomPropertyDefinitionSummary} from '../types'
import {CheckIcon, XIcon} from '@primer/octicons-react'
import {Link} from '@primer/react'

const PropertyNameCell = ({
  name,
  detailsPath,
  managedBySlug,
  getDefinitionListPath,
}: {
  name: string
  detailsPath: string
  managedBySlug: string | null
  getDefinitionListPath: (source: string) => string
}) => {
  return (
    <>
      <Link href={detailsPath}>{name}</Link>
      {managedBySlug && (
        <span className="ml-2">
          (managed by{' '}
          <Link inline href={getDefinitionListPath(managedBySlug)}>
            {managedBySlug}
          </Link>
          )
        </span>
      )}
    </>
  )
}

type DefinitionsTableProps = {
  data: Array<CustomPropertyDefinitionSummary & {id: string}>
  source: string
  getDefinitionDetailsPath: (source: string, property: string) => string
  getDefinitionListPath: (source: string) => string
}

export const DefinitionsTable = ({
  data,
  source,
  getDefinitionDetailsPath,
  getDefinitionListPath,
}: DefinitionsTableProps) => {
  return (
    <DataTable
      data={data}
      columns={[
        {
          header: 'Name',
          field: 'name',
          renderCell: ({name, managedBySlug}) => (
            <PropertyNameCell
              name={name}
              detailsPath={getDefinitionDetailsPath(source, name)}
              managedBySlug={managedBySlug}
              getDefinitionListPath={getDefinitionListPath}
            />
          ),
        },
        {
          header: 'Required',
          field: 'required',
          renderCell: ({required}) => (required ? <CheckIcon size={16} /> : <XIcon size={16} />),
        },
        {header: 'Default value', field: 'defaultValue'},
      ]}
    />
  )
}
